#include <bits/stdc++.h>
using namespace std;
struct Node{string st; uint64_t path;uint64_t ways; uint16_t depth;};
void gen(int n,int a,int b,string &s,vector<string>&v){if((int)s.size()==2*n){v.push_back(s);return;}if(a<n){s+='(';gen(n,a+1,b,s,v);s.pop_back();}if(b<a){s+=')';gen(n,a,b+1,s,v);s.pop_back();}}
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):7;int limit=argc>2?atoi(argv[2]):3000000;vector<string>v;string s;gen(n,0,0,s,v);int N=v.size();vector<Node>nodes;nodes.reserve(min(limit,2000000));unordered_map<string,uint32_t> idx;idx.max_load_factor(0.8);idx.reserve(min(limit,2000000));string init(N,0);idx[init]=0;nodes.push_back({init,0,1,0});uint64_t goals=0;int best=-1;string witness;size_t i=0;while(i<nodes.size()){auto&cur=nodes[i]; if(best!=-1 && cur.depth>=best) break;for(int d=0;d<2;++d){string t=cur.st;bool changed=false,done=true;char c=d?')':'(';for(int j=0;j<N;++j){int p=(unsigned char)t[j];if(p<2*n&&v[j][p]==c){t[j]=p+1;changed=true;}if((unsigned char)t[j]!=2*n)done=false;}if(done){if(best==-1)best=cur.depth+1;if(best==cur.depth+1){goals+=cur.ways;if(witness.empty()){uint64_t path=cur.path|((uint64_t)d<<cur.depth);for(int k=0;k<best;++k)witness+=(path>>k&1)?')':'(';}}continue;}if(!changed)continue;auto it=idx.find(t);if(it==idx.end()){if((int)nodes.size()==limit){cout<<"LIMIT "<<nodes.size()<<"\n";return 1;}auto index=(uint32_t)nodes.size();idx.emplace(t,index);nodes.push_back({move(t),cur.path|((uint64_t)d<<cur.depth),cur.ways,(uint16_t)(cur.depth+1)});}else if(nodes[it->second].depth==cur.depth+1){nodes[it->second].ways+=cur.ways;}}
 ++i;}cout<<"n="<<n<<" dyck="<<N<<" min="<<best<<" optimal_host_words="<<goals<<" reachable_states="<<nodes.size()<<" expanded="<<i<<" witness="<<witness<<"\n";}
